@using sv_0cb3bb0a06f249e8991e1dd66fffd11c.Services
@inject WarehouseState Warehouse
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">
            Currently viewing:
            <strong>@GetWarehouseName(Warehouse.CurrentWarehouseId)</strong>
        </h5>
        <p class="card-text text-muted">
            Use the dropdown in the top bar to switch warehouses. All components on
            this page update automatically.
        </p>
    </div>
</div>

<div class="row">
    <div class="col-md-4">
        <div class="card border-@(AlertService.CurrentAlertCount > 5 ? "danger" : "warning")">
            <div class="card-body text-center">
                <h2 class="display-4">@AlertService.CurrentAlertCount</h2>
                <p class="card-text">Low-Stock Alerts</p>
                <small class="text-muted">Refreshes every 10 seconds</small>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h2 class="display-4">@Warehouse.CurrentWarehouseId</h2>
                <p class="card-text">Active Warehouse ID</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card border-info">
            <div class="card-body text-center">
                <h2 class="display-4">
                    @(AlertService.CurrentAlertCount > 5 ? "⚠️" : "✅")
                </h2>
                <p class="card-text">
                    @(AlertService.CurrentAlertCount > 5 ? "Attention Needed" : "Stock Healthy")
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        Warehouse.OnChange += OnStateChanged;
        AlertService.OnAlertCountChanged += OnStateChanged;

        // Start polling when the dashboard becomes visible
        AlertService.StartPolling();
    }

    private void OnStateChanged() => InvokeAsync(StateHasChanged);

    private static string GetWarehouseName(string id) =>
        WarehouseState.AvailableWarehouses.FirstOrDefault(w => w.Id == id).Name ?? id;

    public void Dispose()
    {
        // Stop polling when the user leaves the dashboard
        AlertService.StopPolling();
        Warehouse.OnChange -= OnStateChanged;
        AlertService.OnAlertCountChanged -= OnStateChanged;
    }
}

